/* wlr-layer-shell glue for ellipse's SDL window.
 *
 * SDL3 creates the window's wl_surface without a role when asked for a
 * custom surface (SDL_PROP_WINDOW_CREATE_WAYLAND_SURFACE_ROLE_CUSTOM_BOOLEAN);
 * this file gives that surface the zwlr_layer_surface_v1 role, on SDL's own
 * wl_display, so SDL keeps handling input and rendering. Our registry and
 * layer-surface objects live on the display's default queue, which SDL's
 * event pump dispatches -- their listeners run inside SDL_PollEvent.
 *
 * The protocol code next to this file is generated by wayland-scanner
 * (layer-shell references xdg_popup, hence xdg-shell too):
 *
 *   wayland-scanner client-header wlr-layer-shell-unstable-v1.xml \
 *     wlr-layer-shell-unstable-v1-client-protocol.h
 *   wayland-scanner private-code wlr-layer-shell-unstable-v1.xml \
 *     wlr-layer-shell-unstable-v1-protocol.c
 *   (and the same two for /usr/share/wayland-protocols/stable/xdg-shell/)
 */

#include <string.h>
#include <stdint.h>
#include <wayland-client.h>

#include "wlr-layer-shell-unstable-v1-client-protocol.h"
#include "xdg-shell-client-protocol.h"

static struct {
    struct wl_display *display;              /* owned by SDL */
    struct wl_surface *surface;              /* owned by SDL */
    struct wl_registry *registry;
    struct zwlr_layer_shell_v1 *shell;
    struct zwlr_layer_surface_v1 *layer;
    uint32_t shell_version;
    int configured;
    int closed;
    uint32_t width, height;                  /* last configure */
    int size_changed;
} st;

static void registry_global(void *data, struct wl_registry *reg, uint32_t name,
                            const char *iface, uint32_t version) {
    (void)data;
    if (strcmp(iface, zwlr_layer_shell_v1_interface.name) == 0 && !st.shell) {
        st.shell_version = version < 4 ? version : 4;
        st.shell = wl_registry_bind(reg, name, &zwlr_layer_shell_v1_interface,
                                    st.shell_version);
    }
}

static void registry_global_remove(void *data, struct wl_registry *reg,
                                   uint32_t name) {
    (void)data; (void)reg; (void)name;
}

static const struct wl_registry_listener registry_listener = {
    .global = registry_global,
    .global_remove = registry_global_remove,
};

static void layer_configure(void *data, struct zwlr_layer_surface_v1 *layer,
                            uint32_t serial, uint32_t width, uint32_t height) {
    (void)data;
    zwlr_layer_surface_v1_ack_configure(layer, serial);
    if (!st.configured || width != st.width || height != st.height)
        st.size_changed = 1;
    st.width = width;
    st.height = height;
    st.configured = 1;
}

static void layer_closed(void *data, struct zwlr_layer_surface_v1 *layer) {
    (void)data; (void)layer;
    st.closed = 1;
}

static const struct zwlr_layer_surface_v1_listener layer_listener = {
    .configure = layer_configure,
    .closed = layer_closed,
};

/* Is zwlr_layer_shell_v1 advertised on this display? Binds it if so. */
int ellipse_layer_available(void *display) {
    if (!display) return 0;
    if (st.registry) return st.shell != NULL;
    st.display = display;
    st.registry = wl_display_get_registry(st.display);
    wl_registry_add_listener(st.registry, &registry_listener, NULL);
    wl_display_roundtrip(st.display);
    return st.shell != NULL;
}

/* Give `surface` the layer-surface role and wait for the first configure.
 * `anchor` is a zwlr_layer_surface_v1 anchor bitmask, `layer` a
 * zwlr_layer_shell_v1 layer, `keyboard` 0 none / 1 exclusive / 2 on-demand.
 * A width or height of 0 lets the compositor fill the anchored span.
 * Returns 1 when configured, 0 on failure. */
int ellipse_layer_attach(void *display, void *surface, const char *ns,
                         int layer, int anchor, int width, int height,
                         int exclusive, int margin_top, int margin_right,
                         int margin_bottom, int margin_left, int keyboard) {
    if (!ellipse_layer_available(display) || !surface) return 0;
    st.surface = surface;
    st.layer = zwlr_layer_shell_v1_get_layer_surface(
        st.shell, st.surface, NULL, (uint32_t)layer, ns ? ns : "ellipse");
    if (!st.layer) return 0;
    zwlr_layer_surface_v1_add_listener(st.layer, &layer_listener, NULL);
    zwlr_layer_surface_v1_set_anchor(st.layer, (uint32_t)anchor);
    zwlr_layer_surface_v1_set_size(st.layer, (uint32_t)width, (uint32_t)height);
    zwlr_layer_surface_v1_set_exclusive_zone(st.layer, exclusive);
    zwlr_layer_surface_v1_set_margin(st.layer, margin_top, margin_right,
                                     margin_bottom, margin_left);
    /* on-demand (2) needs protocol version 4; fall back to none */
    if (keyboard == 2 && st.shell_version < 4) keyboard = 0;
    zwlr_layer_surface_v1_set_keyboard_interactivity(st.layer, (uint32_t)keyboard);
    /* The initial commit carries no buffer: the compositor answers with a
     * configure, which must be acked before anything is attached. */
    wl_surface_commit(st.surface);
    int tries = 0;
    while (!st.configured && !st.closed && tries < 50) {
        if (wl_display_roundtrip(st.display) < 0) return 0;
        tries++;
    }
    return st.configured && !st.closed;
}

/* The size the compositor last configured; returns 1 (once) when it changed
 * since the previous call. */
int ellipse_layer_take_size(int *width, int *height) {
    *width = (int)st.width;
    *height = (int)st.height;
    int changed = st.size_changed;
    st.size_changed = 0;
    return changed;
}

/* The compositor closed the surface (output gone, shell asked). */
int ellipse_layer_closed(void) { return st.closed; }

void ellipse_layer_destroy(void) {
    if (st.layer) { zwlr_layer_surface_v1_destroy(st.layer); st.layer = NULL; }
    if (st.shell) { zwlr_layer_shell_v1_destroy(st.shell); st.shell = NULL; }
    if (st.registry) { wl_registry_destroy(st.registry); st.registry = NULL; }
}
